def find_Rotations(s):
    n = len(s)
    # Try rotations from 1 to n (inclusive of n as fallback for non-periodic strings like "abc")
    for k in range(1, n + 1):
        rotated = s[k:] + s[:k]
        if rotated == s:
            return k

