def sequential_search(arr, element):
    """
    Returns a tuple (found, index).

    - found is True if the element exists in arr and False otherwise.
    - index is 0-based position of the element when found, or -1 if not found.
    """
    for i, val in enumerate(arr):
        if val == element:
            return (True, i)

    # Element not found after checking all items
