def max_aggregate(data):
    # Dictionary to store cumulative scores for each person
    totals = {}

    # Iterate over the list of (name, score) tuples
    for name, score in data:
        if name not in totals:
            totals[name] = 0

        totals[name] += score

    # Find the maximum aggregate from the dictionary values and corresponding names
    max_name = None
    max_score = float('-inf')

    for person, total in totals.items():
        if total > max_score:
            max_score = total
            max_name = person

    return (max_name, max_score)

